// ── Parse + normalise all Yahoo Finance responses ──────────────────────
const items = [];
for (const item of $input.all()) {
  try {
    const result = item.json.chart.result[0];
    const meta   = result.meta;
    const quote  = result.indicators.quote[0];
    const idx    = quote.close.length - 1;
    items.push({
      ticker:    meta.symbol,
      date:      new Date().toISOString().slice(0, 10),
      open:      quote.open[idx],
      high:      quote.high[idx],
      low:       quote.low[idx],
      close:     quote.close[idx],
      volume:    quote.volume[idx],
      currency:  meta.currency,
      source:    'yahoo',
      timestamp: new Date().toISOString()
    });
  } catch(e) { /* skip malformed */ }
}
console.log(`[TradeIQ] Parsed ${items.length} Yahoo records`);
return items;

// ── Parse CoinGecko response ─────────────────────────────────────────────
const data = $input.first().json;
const coinMap = {
  bitcoin:     'BTC-USD',
  ethereum:    'ETH-USD',
  binancecoin: 'BNB-USD',
  solana:      'SOL-USD'
};
const items = [];
for (const [id, ticker] of Object.entries(coinMap)) {
  if (!data[id]) continue;
  items.push({
    ticker,
    date:       new Date().toISOString().slice(0, 10),
    close:      data[id].usd,
    change_24h: data[id].usd_24h_change,
    market_cap: data[id].usd_market_cap,
    source:     'coingecko',
    timestamp:  new Date().toISOString()
  });
}
console.log(`[TradeIQ] Parsed ${items.length} crypto records`);
return items;

// ── In-workflow VADER-like sentiment scoring ──────────────────────────────
// Fast approximate scoring using keyword lists (full VADER runs in Python)
const POSITIVE = ['surge','soar','gain','profit','beats','record','bullish','rises','rally','growth','buy','upgrade','strong','positive','higher','beat','dividend','expand'];
const NEGATIVE = ['fall','crash','loss','drop','bearish','decline','plunge','sell','downgrade','weak','miss','sue','fraud','warn','lower','cut','volatile','risk'];

const allItems = $input.all();
const results = [];
const headlines = [];

for (const item of allItems) {
  // Try to parse RSS XML text
  const text = typeof item.json === 'string' ? item.json : JSON.stringify(item.json);
  // Extract titles from the RSS body
  const titleMatches = text.match(/<title><![\[\]!CDATA]*([^<]+)/g) || [];

  for (const match of titleMatches.slice(0, 10)) {
    const headline = match.replace(/<[^>]+>/g, '').replace('CDATA[', '').trim();
    if (headline.length < 5) continue;

    const lower = headline.toLowerCase();
    let score = 0;
    POSITIVE.forEach(w => { if (lower.includes(w)) score += 0.1; });
    NEGATIVE.forEach(w => { if (lower.includes(w)) score -= 0.1; });
    score = Math.max(-1, Math.min(1, score));

    headlines.push({ headline, score });
  }
}

// Aggregate overall market sentiment
const avgScore = headlines.length > 0
  ? headlines.reduce((s, h) => s + h.score, 0) / headlines.length
  : 0;

const label = avgScore > 0.05 ? 'Bullish 📈' : (avgScore < -0.05 ? 'Bearish 📉' : 'Neutral ➡️');

console.log(`[TradeIQ] News sentiment: ${label} (${avgScore.toFixed(3)}) from ${headlines.length} headlines`);

return [{
  market_sentiment_score: parseFloat(avgScore.toFixed(4)),
  market_sentiment_label: label,
  headline_count: headlines.length,
  top_headlines: headlines.slice(0, 5),
  timestamp: new Date().toISOString()
}];

// ── Signal Router: Filter BUY/SELL/HOLD signals ──────────────────────────
const predResult  = $('Python: ML Ensemble Predict').first().json;
const sentResult  = $('VADER Sentiment Score').first().json;

const signals   = predResult.signals || [];
const mktSent   = sentResult.market_sentiment_score || 0;

const buySignals  = [];
const sellSignals = [];
const holdSignals = [];
const tradeAlerts = [];

for (const s of signals) {
  const row = {
    ticker:          s.ticker,
    signal:          s.signal,
    confidence:      s.confidence,
    change_pct:      s.change_pct,
    last_price:      s.last_price,
    predicted_price: s.predicted_price,
    rsi:             s.rsi,
    ind_signal:      s.ind_signal,
    ind_score:       s.ind_score,
    market_sentiment: mktSent,
  };

  if (s.signal === 'BUY' && s.confidence >= 0.35) {
    buySignals.push(row);
    tradeAlerts.push({ ...row, action: 'BUY 🟢', emoji: '🟢' });
  } else if (s.signal === 'SELL') {
    sellSignals.push(row);
    tradeAlerts.push({ ...row, action: 'SELL 🔴', emoji: '🔴' });
  } else {
    holdSignals.push(row);
  }
}

console.log(`[Signal Router] BUY:${buySignals.length} SELL:${sellSignals.length} HOLD:${holdSignals.length}`);

return [{
  buy_count:    buySignals.length,
  sell_count:   sellSignals.length,
  hold_count:   holdSignals.length,
  total:        signals.length,
  buy_signals:  buySignals,
  sell_signals: sellSignals,
  trade_alerts: tradeAlerts,
  market_sentiment: mktSent,
  timestamp: new Date().toISOString()
}];

// ── Build Telegram alert message ─────────────────────────────────────────
const cycleResult   = $('Execute Trades (BUY/SELL Agents)').first().json;
const signalResult  = $('Signal Router').first().json;
const portfolioData = $('Portfolio Status').first().json;

const summary  = cycleResult.summary || {};
const cash     = portfolioData.cash || 0;
const openPos  = (portfolioData.open_positions || []).length;
const mktSent  = signalResult.market_sentiment || 0;
const sentLabel = mktSent > 0.05 ? 'Bullish 📈' : (mktSent < -0.05 ? 'Bearish 📉' : 'Neutral ➡️');

const ts = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

let msg = `🤖 *TradeIQ Auto-Trader Report*\n`;
msg += `🕐 ${ts} IST\n\n`;
msg += `📊 *Market Sentiment:* ${sentLabel} (${mktSent.toFixed(3)})\n`;
msg += `💰 *Portfolio Cash:* ₹${cash.toLocaleString('en-IN')}\n`;
msg += `📂 *Open Positions:* ${openPos}\n\n`;
msg += `✅ *BUY signals:* ${signalResult.buy_count}\n`;
msg += `❌ *SELL signals:* ${signalResult.sell_count}\n`;
msg += `➡️ *HOLD:* ${signalResult.hold_count}\n\n`;
msg += `📈 *Trades this cycle:* Buys=${summary.buys || 0}, Sells=${summary.sells || 0}, Skipped=${summary.skipped || 0}\n\n`;

// Top trade alerts
const alerts = signalResult.trade_alerts || [];
if (alerts.length > 0) {
  msg += `🚨 *Active Signals:*\n`;
  for (const a of alerts.slice(0, 5)) {
    msg += `${a.emoji} ${a.ticker}: ${a.action} @ ₹${(a.last_price||0).toFixed(2)} (Conf: ${((a.confidence||0)*100).toFixed(0)}%)`;
    msg += ` | Δ${(a.change_pct||0).toFixed(2)}%\n`;
  }
}

console.log('[TradeIQ] Telegram message prepared');
return [{ message: msg }];

// ── Prepare Google Sheets row ─────────────────────────────────────────────
const cycleResult   = $('Execute Trades (BUY/SELL Agents)').first().json;
const signalResult  = $('Signal Router').first().json;
const portfolioData = $('Portfolio Status').first().json;

const summary = cycleResult.summary || {};
const cash    = portfolioData.cash || 0;
const openPos = (portfolioData.open_positions || []).length;
const ts      = new Date().toISOString();

// One row per cycle
return [{
  timestamp:       ts,
  cash:            cash,
  open_positions:  openPos,
  buys:            summary.buys || 0,
  sells:           summary.sells || 0,
  skipped:         summary.skipped || 0,
  buy_signals:     signalResult.buy_count || 0,
  sell_signals:    signalResult.sell_count || 0,
  hold_signals:    signalResult.hold_count || 0,
  market_sentiment: signalResult.market_sentiment || 0,
}];
